from collections import deque
def transform(g):
 g=[row[:] for row in g]; H=len(g); W=len(g[0]); seen=set()
 # detect solid rectangular-outline components by bounding-box pixels same color
 for y in range(H):
  for x in range(W):
   c=g[y][x]
   if c==3 or (y,x) in seen: continue
   q=[(y,x)]; seen.add((y,x)); comp=[]
   while q:
    a,b=q.pop();comp.append((a,b))
    for na,nb in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
     if 0<=na<H and 0<=nb<W and (na,nb) not in seen and g[na][nb]==c: seen.add((na,nb));q.append((na,nb))
   ys=[a for a,b in comp];xs=[b for a,b in comp]; y0,y1=min(ys),max(ys);x0,x1=min(xs),max(xs)
   if len(comp)==2*(y1-y0+1)+2*(x1-x0+1)-4 and y1-y0>=2 and x1-x0>=2:
    fill=2 if ((y1-y0-1)*(x1-x0-1))%2==0 else 7
    for a in range(y0+1,y1):
     for b in range(x0+1,x1):
      if g[a][b]==3:g[a][b]=fill
 return g
